function load(key=KEY){let s={};try{s=JSON.parse(localStorage.getItem(key)||"{}")}catch(_){}return {...base,...s,notifications:{...base.notifications,...(s.notifications||{})},reports:{...base.reports,...(s.reports||{})},privacy:{...base.privacy,...(s.privacy||{})}}}
let activeKey=KEY,activeUserId=null,p=load(activeKey),originals=new WeakMap();
function get(){return JSON.parse(JSON.stringify(p))}
function translate(s){return (D[p.language]||{})[s]||s}
function node(n){if(n.nodeType===3){const parent=n.parentElement;if(!parent||["SCRIPT","STYLE","TEXTAREA","INPUT","CODE","PRE"].includes(parent.tagName)||parent.closest("[data-no-translate]"))return;if(!originals.has(n))originals.set(n,n.nodeValue);let o=originals.get(n),t=o.trim();if(t){let v=translate(t),out=v===t?o:o.replace(t,v);if(n.nodeValue!==out)n.nodeValue=out}return}if(n.nodeType!==1)return;["placeholder","title","aria-label"].forEach(a=>{if(!n.hasAttribute(a))return;let d=originals.get(n);if(!d){d={};originals.set(n,d)}let k="attr:"+a;if(!(k in d))d[k]=n.getAttribute(a);let v=translate(d[k]);if(n.getAttribute(a)!==v)n.setAttribute(a,v)});if(["SCRIPT","STYLE","TEXTAREA","INPUT","CODE","PRE"].includes(n.tagName)||n.closest("[data-no-translate]"))return;n.childNodes.forEach(node)}
function applyLanguage(){document.documentElement.lang=p.language;document.documentElement.dir=["ar","ur"].includes(p.language)?"rtl":"ltr";if(document.body)node(document.body)}
function applyTheme(){document.documentElement.dataset.theme=p.theme==="light"?"light":"dark";document.documentElement.style.colorScheme=p.theme==="light"?"light":"dark"}
function update(v){const previous=p;p={...p,...v,notifications:{...p.notifications,...(v.notifications||{})},reports:{...p.reports,...(v.reports||{})},privacy:{...p.privacy,...(v.privacy||{})}};try{localStorage.setItem(activeKey,JSON.stringify(p))}catch(_){p=previous;applyTheme();applyLanguage();throw new Error("Browser storage is unavailable; the preference was not saved.")}applyTheme();applyLanguage();window.dispatchEvent(new CustomEvent("cleantrack:preferences-changed",{detail:get()}));return get()}
function setUser(id,serverPreferences){const nextKey=id===null||id===undefined||id===""?KEY:KEY+".user."+String(id);activeUserId=id===null||id===undefined||id===""?null:String(id);if(nextKey!==activeKey){activeKey=nextKey;let saved=false;try{saved=localStorage.getItem(activeKey)!==null}catch(_){}p=load(activeKey);if(!saved&&activeKey!==KEY){p=load(KEY);try{localStorage.setItem(activeKey,JSON.stringify(p))}catch(_){}}}if(serverPreferences&&typeof serverPreferences==="object"&&Object.keys(serverPreferences).length){p={...p,...serverPreferences,notifications:{...p.notifications,...(serverPreferences.notifications||{})},reports:{...p.reports,...(serverPreferences.reports||{})},privacy:{...p.privacy,...(serverPreferences.privacy||{})}};try{localStorage.setItem(activeKey,JSON.stringify(p))}catch(_){}}applyTheme();applyLanguage();return get()}
async function sync(){if(!activeUserId)throw new Error("Sign in to save preferences to your account.");const api=window.CleanTrackApi;if(!api||typeof api.patch!=="function")throw new Error("The account settings API is unavailable.");const response=await api.patch("auth/me",{preferences:get()});if(response&&response.user&&response.user.preferences){setUser(activeUserId,response.user.preferences)}return get()}
function formatCurrency(n,c=p.currency){try{return new Intl.NumberFormat(({en:"en-GB",es:"es",ar:"ar",hi:"hi-IN",ur:"ur",zh:"zh-CN"})[p.language]||"en-GB",{style:"currency",currency:c}).format(Number(n))}catch(_){return String(n)+" "+c}}
function formatDate(v){let d=new Date(v);if(Number.isNaN(+d))return "—";let o={timeZone:p.timeZone,year:"numeric",month:"2-digit",day:"2-digit"};if(p.dateFormat==="MM/DD/YYYY")return new Intl.DateTimeFormat("en-US",o).format(d);if(p.dateFormat==="DD Mon YYYY")return new Intl.DateTimeFormat(p.language,{...o,day:"2-digit",month:"short"}).format(d);return new Intl.DateTimeFormat(p.dateFormat==="DD/MM/YYYY"?"en-GB":"en-CA",o).format(d)}
function formatTime(v){return new Intl.DateTimeFormat(p.language,{timeZone:p.timeZone,hour:"2-digit",minute:"2-digit",hour12:p.timeFormat==="12"}).format(new Date(v))}
applyTheme();if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",applyLanguage,{once:true});else applyLanguage();new MutationObserver(rs=>rs.forEach(r=>{if(r.type==="childList")r.addedNodes.forEach(node);else if(r.type==="attributes")node(r.target);else node(r.target)})).observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:["placeholder","title","aria-label"]});

